using System;using System.Collections.Generic;using System.Linq;using System.Threading.Tasks;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Logging;using accounts-management.Models;using accounts-management.Services;namespace accounts-management.Controllers{[ApiController][Route("api/[controller]")]public class AccountsController : ControllerBase{private readonly IAccountService _service;private readonly ILogger<AccountsController> _logger;public AccountsController(IAccountService service, ILogger<AccountsController> logger){_service=service;_logger=logger;}[HttpGet]public async Task<ActionResult<IEnumerable<Account>>> GetAll(){try{var accounts=await _service.GetAllAsync();return Ok(accounts);}catch(Exception ex){_logger.LogError(ex,"Error fetching accounts");return Problem(detail:"An error occurred while fetching accounts.",statusCode:StatusCodes.Status500InternalServerError);}}[HttpGet("{id:long}")]public async Task<ActionResult<Account>> GetById(long id){try{var account=await _service.GetByIdAsync(id);if(account==null)return NotFound();return Ok(account);}catch(Exception ex){_logger.LogError(ex,"Error fetching account {Id}",id);return Problem(detail:"An error occurred while fetching the account.",statusCode:StatusCodes.Status500InternalServerError);}}[HttpPost("bulk")]public async Task<ActionResult<IEnumerable<Account>>> CreateMany([FromBody] IEnumerable<AccountCreateDto> accounts){if(accounts==null||!accounts.Any())return BadRequest(new { message="Request body must contain at least one account"});try{var created=await _service.CreateManyAsync(accounts);return StatusCode(StatusCodes.Status201Created,created);}catch(ArgumentException aex){_logger.LogWarning(aex,"Validation failed for bulk create");return BadRequest(new { message=aex.Message});}catch(Exception ex){_logger.LogError(ex,"Error creating accounts in bulk");return Problem(detail:"An error occurred while creating accounts.",statusCode:StatusCodes.Status500InternalServerError);}}[HttpPut("{id:long}")]public async Task<ActionResult<Account>> Update(long id,[FromBody] AccountUpdateDto dto){if(dto==null)return BadRequest(new { message="Invalid payload"});try{var updated=await _service.UpdateAsync(id,dto);if(updated==null)return NotFound();return Ok(updated);}catch(ArgumentException aex){_logger.LogWarning(aex,"Validation failed for update {Id}",id);return BadRequest(new { message=aex.Message});}catch(Exception ex){_logger.LogError(ex,"Error updating account {Id}",id);return Problem(detail:"An error occurred while updating the account.",statusCode:StatusCodes.Status500InternalServerError);}}[HttpDelete("{id:long}")]public async Task<IActionResult> Delete(long id){try{var deleted=await _service.DeleteAsync(id);if(!deleted)return NotFound();return NoContent();}catch(Exception ex){_logger.LogError(ex,"Error deleting account {Id}",id);return Problem(detail:"An error occurred while deleting the account.",statusCode:StatusCodes.Status500InternalServerError);}}}}